param([string]$StorageAccountName,[string]$ResourceGroupName,[string]$ContainerName,[int]$Days,[string]$RuleName)
$ErrorActionPreference = 'Stop'
$action = Add-AzStorageAccountManagementPolicyAction -BaseBlobAction Delete -DaysAfterModificationGreaterThan $Days
$filter = New-AzStorageAccountManagementPolicyFilter -PrefixMatch $ContainerName -BlobType blockBlob
$newRule = New-AzStorageAccountManagementPolicyRule -Name $RuleName -Action $action -Filter $filter
$rules = @()
$maxAttempts = 10
for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
  try {
    $rules = @()
    try {
      $existing = Get-AzStorageAccountManagementPolicy -ResourceGroupName $ResourceGroupName -StorageAccountName $StorageAccountName -ErrorAction Stop
      if ($existing -and $existing.Rules) { $rules = @($existing.Rules | Where-Object { $_.Name -ne $RuleName }) }
    } catch { Write-Host 'No existing management policy found or not yet readable.' }
    $rules += $newRule
    Set-AzStorageAccountManagementPolicy -ResourceGroupName $ResourceGroupName -StorageAccountName $StorageAccountName -Rule $rules | Out-Null
    Write-Host "Lifecycle rule '$RuleName' applied. Total rules: $($rules.Count)"
    break
  } catch {
    if ($attempt -eq $maxAttempts) { throw }
    Write-Host "Attempt $attempt failed: $($_.Exception.Message). Retrying in 30s (waiting for RBAC propagation)..."
    Start-Sleep -Seconds 30
  }
}
$DeploymentScriptOutputs = @{}
$DeploymentScriptOutputs['ruleCount'] = [string]$rules.Count
$DeploymentScriptOutputs['rules'] = (($rules | ForEach-Object { $_.Name }) -join ',')

properties.query:
let lookback = 14d;
let perUserCountry =
    BroadcomCloudSWG_CL
    | where TimeGenerated > ago(lookback)
    | where isnotempty(DstCountry) and DstCountry != "-"
    | summarize CountryCount = count() by UserName, DstCountry;
let userTotals =
    perUserCountry
    | summarize TotalForUser = sum(CountryCount), DistinctCountries = dcount(DstCountry) by UserName;
perUserCountry
| join kind=inner userTotals on UserName
| extend CountryShare = round(todouble(CountryCount) / TotalForUser, 4)
| where CountryCount <= 3 and CountryShare < 0.05 and DistinctCountries > 1
| order by CountryShare asc
